0e73ed04932a76fcdd13bb12740f66d8ce6299c3:
query readerVersionsQuery(
  $count: Int = 20
  $id: ID!
) {
  manifestation(id: $id) {
    id
    versions {
      pendingCount
      acceptedCount
      pending(first: $count) {
        edges {
          cursor
          node {
            id
            fieldName
            source
            newValue
            status
            confidenceScore
            matchType
            observationCount
          }
        }
        pageInfo {
          hasNextPage
          hasPreviousPage
          startCursor
          endCursor
        }
      }
    }
  }
}

