3970a01d82ff13f7ce380de05032a2bea5e5504e:
query readerNodeQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    id
    ... on Manifestation {
      ...readerBook
    }
    ... on Work {
      ...readerWork
    }
    ... on Shelf {
      name
      isSystem
      itemCount
      createdAt
      updatedAt
    }
    ... on Series {
      name
    }
    ... on Viewer {
      displayName
      isChild
    }
  }
}

