query readerSeriesQuery(
  $manifestationCount: Int = 2
  $count: Int = 50
  $id: ID!
  $after: String
) {
  series(id: $id) {
    id
    name
    works(first: $count, after: $after) {
      edges {
        cursor
        position
        node {
          ...readerWork
          manifestations(first: $manifestationCount) {
            edges {
              cursor
              node {
                ...readerBook
                id
              }
            }
            pageInfo {
              hasNextPage
              hasPreviousPage
              startCursor
              endCursor
            }
          }
          id
        }
      }
      pageInfo {
        hasNextPage
        hasPreviousPage
        startCursor
        endCursor
      }
    }
  }
}

